<?php
declare(strict_types=1);
require 'kms_functions.php';
$user=kms_require_role(['seller','staff','manager','admin']);
$edit=(int)($_GET['edit']??0); $existing=null; $error='';
if($edit){$s=$pdoKms->prepare('SELECT * FROM kms_knowledge_items WHERE id=?');$s->execute([$edit]);$existing=$s->fetch();if(!$existing)die('Knowledge tidak ditemukan.');}
$cats=$pdoKms->query("SELECT id,name FROM kms_categories WHERE is_active=1 ORDER BY name")->fetchAll();
$rev=null;if($existing){$s=$pdoKms->prepare('SELECT * FROM kms_knowledge_revisions WHERE knowledge_id=? ORDER BY version_number DESC LIMIT 1');$s->execute([$edit]);$rev=$s->fetch();}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$title=trim($_POST['title']??'');$summary=trim($_POST['summary']??'');$content=trim($_POST['content']??'');$type=$_POST['knowledge_type']??'article';$nature=$_POST['knowledge_nature']??'explicit';$cat=(int)($_POST['category_id']??0);$vis=$_POST['visibility']??'employees';$change=trim($_POST['change_summary']??'');if($title===''||$content==='')$error='Judul dan isi wajib diisi.';elseif(!in_array($type,['article','sop','guide','faq','best_practice','lesson_learned','troubleshooting','policy','other'],true))$error='Type tidak valid.';else{try{$pdoKms->beginTransaction();if(!$edit){$slug=kms_unique_slug($pdoKms,kms_slugify($title));$s=$pdoKms->prepare("INSERT INTO kms_knowledge_items(title,slug,summary,knowledge_nature,knowledge_type,category_id,status,visibility,owner_user_id,created_by_user_id) VALUES(?,?,?,?,?,?,'draft',?,?,?)");$s->execute([$title,$slug,$summary?:null,$nature,$type,$cat?:null,$vis,$user['id'],$user['id']]);$kid=(int)$pdoKms->lastInsertId();$pdoKms->prepare("INSERT INTO kms_knowledge_revisions(knowledge_id,version_number,title,content,change_summary,created_by_user_id,is_current) VALUES(?,1,?,?,?, ?,1)")->execute([$kid,$title,$content,$change?:'Initial knowledge capture',$user['id']]);}else{$s=$pdoKms->prepare('SELECT COALESCE(MAX(version_number),0) FROM kms_knowledge_revisions WHERE knowledge_id=?');$s->execute([$edit]);$ver=(int)$s->fetchColumn()+1;$pdoKms->prepare('UPDATE kms_knowledge_revisions SET is_current=0 WHERE knowledge_id=?')->execute([$edit]);$pdoKms->prepare("INSERT INTO kms_knowledge_revisions(knowledge_id,version_number,title,content,change_summary,created_by_user_id,is_current) VALUES(?,?,?,?,?,?,1)")->execute([$edit,$ver,$title,$content,$change?:'Updated content',$user['id']]);$pdoKms->prepare("UPDATE kms_knowledge_items SET title=?,slug=?,summary=?,knowledge_nature=?,knowledge_type=?,category_id=?,visibility=?,updated_by_user_id=? WHERE id=?")->execute([$title,kms_unique_slug($pdoKms,kms_slugify($title),$edit),$summary?:null,$nature,$type,$cat?:null,$vis,$user['id'],$edit]);$kid=$edit;}$pdoKms->commit();redirect('knowledge_view.php?id='.$kid);}catch(Throwable $e){if($pdoKms->inTransaction())$pdoKms->rollBack();$error='Gagal menyimpan: '.$e->getMessage();}}}
$title=$existing?'Edit Knowledge':'Capture Knowledge';include 'kms_layout_top.php'; ?>
<div class="page-headline"><div><div class="eyebrow">KNOWLEDGE CAPTURE</div><h1><?=e($title)?></h1><p>Dokumentasikan pengalaman, prosedur, dan pengetahuan kerja.</p></div><a class="btn btn-soft" href="knowledge.php">Cancel</a></div><?php if($error):?><div class="alert alert-error"><?=e($error)?></div><?php endif;?><form method="POST" class="editor-layout"><section class="card editor-main"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="form-group"><label>Title</label><input name="title" required value="<?=e($existing['title']??'')?>" placeholder="Contoh: Prosedur Penanganan Selisih Stok"></div><div class="form-group"><label>Summary</label><textarea name="summary" rows="3" placeholder="Ringkasan singkat..."><?=e($existing['summary']??'')?></textarea></div><div class="form-group"><label>Content</label><textarea class="content-editor" name="content" rows="20" required placeholder="Tulis knowledge secara lengkap..."><?=e($rev['content']??'')?></textarea></div><div class="form-group"><label>Revision Summary</label><input name="change_summary" placeholder="Apa yang berubah pada versi ini?"></div><button class="btn btn-primary" type="submit"><?= $existing?'Save New Revision':'Save Knowledge'?></button></section><aside class="editor-side"><section class="card"><h3>Classification</h3><div class="form-group"><label>Type</label><select name="knowledge_type"><?php foreach(['article','sop','guide','faq','best_practice','lesson_learned','troubleshooting','policy','other'] as $o):?><option value="<?=$o?>" <?=($existing['knowledge_type']??'article')===$o?'selected':''?>><?=e(ucwords(str_replace('_',' ',$o)))?></option><?php endforeach;?></select></div><div class="form-group"><label>Nature</label><select name="knowledge_nature"><?php foreach(['explicit','tacit','combined'] as $o):?><option value="<?=$o?>" <?=($existing['knowledge_nature']??'explicit')===$o?'selected':''?>><?=ucfirst($o)?></option><?php endforeach;?></select></div><div class="form-group"><label>Category</label><select name="category_id"><option value="0">Uncategorized</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=isset($existing['category_id'])&&(int)$existing['category_id']===(int)$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="form-group"><label>Visibility</label><select name="visibility"><option value="public" <?=($existing['visibility']??'')==='public'?'selected':''?>>Public / Buyer</option><option value="employees" <?=($existing['visibility']??'employees')==='employees'?'selected':''?>>All Employees</option><option value="management" <?=($existing['visibility']??'')==='management'?'selected':''?>>Management</option></select></div></section><section class="card"><div class="info-box"><strong>Draft workflow</strong><p>Knowledge disimpan sebagai draft; tahap approval/publishing dapat diperluas sesudah frontend dasar stabil.</p></div></section></aside></form><?php include 'kms_layout_bottom.php'; ?>
